export type SpanPluginPdas = {
  config: typeof findConfigPda;
  bidUsdc: typeof findBidUsdcPda;
  resale: typeof findResalePda;
  bidSpan: typeof findBidSpanPda;
  band: typeof findBandPda;
  vault: typeof findVaultPda;
  until: typeof findUntilPda;
  requestUsdc: typeof findRequestUsdcPda;
  requestSpan: typeof findRequestSpanPda;
  ticket: typeof findTicketPda;
  candle: typeof findCandlePda;
  bid: typeof findBidPda;
  request: typeof findRequestPda;
};

export type SpanPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function spanProgram() {
  return <T extends SpanPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { span: SpanPlugin }> => {
    return extendClient(client, {
      span: <SpanPlugin>{
        accounts: {
          band: addSelfFetchFunctions(client, getBandCodec()),
          bid: addSelfFetchFunctions(client, getBidCodec()),
          candle: addSelfFetchFunctions(client, getCandleCodec()),
          config: addSelfFetchFunctions(client, getConfigCodec()),
          request: addSelfFetchFunctions(client, getRequestCodec()),
          resale: addSelfFetchFunctions(client, getResaleCodec()),
          ticket: addSelfFetchFunctions(client, getTicketCodec()),
          until: addSelfFetchFunctions(client, getUntilCodec()),
        },
        instructions: {
          acceptBid: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAcceptBidInstructionAsync(input),
            ),
          bidSpan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getBidSpanInstructionAsync(input),
            ),
          buy: (input) =>
            addSelfPlanAndSendFunctions(client, getBuyInstructionAsync(input)),
          buyResale: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getBuyResaleInstructionAsync(input),
            ),
          buyRunning: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getBuyRunningInstructionAsync(input),
            ),
          closeBand: (input) =>
            addSelfPlanAndSendFunctions(client, getCloseBandInstruction(input)),
          closeBid: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseBidInstructionAsync(input),
            ),
          closeRequest: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseRequestInstructionAsync(input),
            ),
          closeResale: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseResaleInstruction(input),
            ),
          closeUntil: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseUntilInstruction(input),
            ),
          fillRequestHeld: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillRequestHeldInstructionAsync(input),
            ),
          fillRequestOpen: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillRequestOpenInstructionAsync(input),
            ),
          fillRequestRunning: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillRequestRunningInstructionAsync(input),
            ),
          init: (input) =>
            addSelfPlanAndSendFunctions(client, getInitInstructionAsync(input)),
          listResale: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getListResaleInstructionAsync(input),
            ),
          loadSpan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getLoadSpanInstructionAsync(input),
            ),
          mark: (input) =>
            addSelfPlanAndSendFunctions(client, getMarkInstructionAsync(input)),
          openCandle: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenCandleInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          openRunning: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenRunningInstructionAsync(input),
            ),
          openTicket: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenTicketInstructionAsync(input),
            ),
          placeBid: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPlaceBidInstructionAsync(input),
            ),
          placeRequest: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPlaceRequestInstructionAsync(input),
            ),
          read: (input) =>
            addSelfPlanAndSendFunctions(client, getReadInstructionAsync(input)),
          requestSpan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRequestSpanInstructionAsync(input),
            ),
          setFeed: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetFeedInstructionAsync(input),
            ),
          setMarker: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetMarkerInstructionAsync(input),
            ),
          setParams: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetParamsInstructionAsync(input),
            ),
          setSpan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetSpanInstructionAsync(input),
            ),
          settle: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleInstructionAsync(input),
            ),
          withdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawInstructionAsync(input),
            ),
        },
        pdas: {
          config: findConfigPda,
          bidUsdc: findBidUsdcPda,
          resale: findResalePda,
          bidSpan: findBidSpanPda,
          band: findBandPda,
          vault: findVaultPda,
          until: findUntilPda,
          requestUsdc: findRequestUsdcPda,
          requestSpan: findRequestSpanPda,
          ticket: findTicketPda,
          candle: findCandlePda,
          bid: findBidPda,
          request: findRequestPda,
        },
        identifyAccount: identifySpanAccount,
        identifyInstruction: identifySpanInstruction,
        parseInstruction: parseSpanInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
